#!/usr/bin/env node
// Validate the referential and regenerate what derives from it. Zero dependencies.
//
//   node tools/build.mjs           validate, then write docs/fr/REFERENTIEL.md, docs/en/REFERENTIAL.md
//                                  and the version (from VERSION) into plugin.json and marketplace.json
//   node tools/build.mjs --check   same validation; fails if a generated file is out of date (CI)
import { readFileSync, writeFileSync, readdirSync, existsSync, mkdirSync } from "node:fs";
import { join, dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const PLUGIN = join(ROOT, "plugins", "umd");
const REF = join(PLUGIN, "referential");
const check = process.argv.includes("--check");
const errors = [];
const stale = [];
const readJson = (p) => JSON.parse(readFileSync(p, "utf8"));

const VERSION = readFileSync(join(ROOT, "VERSION"), "utf8").trim();
const scoring = readJson(join(REF, "scoring.json"));
const groups = readdirSync(join(REF, "domains")).filter((f) => f.endsWith(".json")).sort().map((f) => readJson(join(REF, "domains", f)));
const licenses = readJson(join(REF, "licenses.json"));
readJson(join(REF, "slop-words.json"));

// ---- validation
const TOOLS = new Set(["analyze", "lint", "licenses", "determinism", "vmaf", "captions_check", "webperf"]);
const SEV = new Set(Object.keys(scoring.scoring.severity_weight));
const FLAGS = new Set([...Object.keys(scoring.flags), ...Object.keys(scoring.derived_flags)]);
const ids = new Set();
const domainIds = [];
for (const g of groups) {
  if (!g.group || !g.label?.fr || !g.label?.en) errors.push(`group without id or label`);
  for (const d of g.domains) {
    domainIds.push(d.id);
    for (const k of ["id", "code"]) if (!d[k]) errors.push(`domain in ${g.group} without ${k}`);
    if (!d.label?.fr || !d.label?.en || !d.summary?.fr || !d.summary?.en) errors.push(`${d.id}: label/summary must be fr+en`);
    for (const f of d.applies_if || []) if (!FLAGS.has(f)) errors.push(`${d.id}: unknown flag ${f}`);
    for (const b of d.build || []) if (!b.fr || !b.en) errors.push(`${d.id}: build rule must be fr+en`);
    for (const c of d.criteria) {
      if (ids.has(c.id)) errors.push(`duplicate criterion ${c.id}`);
      ids.add(c.id);
      if (!c.id.startsWith(`${d.code}-`)) errors.push(`${c.id}: must start with ${d.code}-`);
      if (!SEV.has(c.severity)) errors.push(`${c.id}: bad severity ${c.severity}`);
      if (!["auto", "inspect"].includes(c.check?.method)) errors.push(`${c.id}: check.method must be auto or inspect`);
      if (c.check?.method === "auto" && !TOOLS.has(c.check.tool)) errors.push(`${c.id}: unknown tool ${c.check.tool}`);
      for (const f of c.applies_if || []) if (!FLAGS.has(f)) errors.push(`${c.id}: unknown flag ${f}`);
      for (const k of ["label", "verify"]) if (!c[k]?.fr || !c[k]?.en) errors.push(`${c.id}: ${k} must be fr+en`);
    }
  }
}
for (const [name, p] of Object.entries(scoring.profiles)) {
  for (const d of domainIds) if (!(d in p.weights)) errors.push(`profile ${name}: no weight for ${d}`);
  for (const d of Object.keys(p.weights)) if (!domainIds.includes(d)) errors.push(`profile ${name}: unknown domain ${d}`);
  for (const f of p.default_flags) if (!FLAGS.has(f)) errors.push(`profile ${name}: unknown flag ${f}`);
}
for (const e of licenses.entries) if (!licenses.classes[e.class]) errors.push(`licence entry ${e.match[0]}: unknown class ${e.class}`);
// auto criteria must be produced by autocheck
const auto = readFileSync(join(PLUGIN, "scripts", "lib", "autocheck.mjs"), "utf8");
for (const g of groups) for (const d of g.domains) for (const c of d.criteria) {
  if (c.check.method === "auto" && !auto.includes(`"${c.id}"`)) errors.push(`${c.id}: auto criterion not handled in autocheck.mjs`);
}
// skills and agents need frontmatter with name and description
for (const dir of ["skills", "agents"]) {
  const base = join(PLUGIN, dir);
  for (const e of readdirSync(base, { withFileTypes: true })) {
    const f = e.isDirectory() ? join(base, e.name, "SKILL.md") : join(base, e.name);
    if (!f.endsWith(".md") || !existsSync(f)) continue;
    const head = readFileSync(f, "utf8").match(/^---\n([\s\S]*?)\n---/);
    if (!head || !/^name:/m.test(head[1]) || !/^description:/m.test(head[1])) errors.push(`${f}: missing frontmatter name/description`);
  }
}
if (errors.length) { console.error(`Referential invalid:\n- ${errors.join("\n- ")}`); process.exit(1); }

// ---- generation
const write = (path, text) => {
  const cur = existsSync(path) ? readFileSync(path, "utf8") : null;
  if (cur === text) return;
  if (check) { stale.push(path); return; }
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, text);
};
const GEN = "<!-- Generated by tools/build.mjs from plugins/umd/referential. Do not edit by hand. -->";
function doc(lang) {
  const t = lang === "fr"
    ? { title: "Référentiel qualité motion", intro: "Critères audités par `/umd:audit`. Méthode `auto` : décidé dans le code à partir des mesures ; `inspect` : jugé par un agent auditeur avec une preuve.", profiles: "Profils et poids des domaines", sev: { blocker: "bloquant", major: "majeur", minor: "mineur" }, cols: ["ID", "Critère", "Sévérité", "Méthode", "Vérification"], th: "Seuils par défaut", rules: "Règles de construction", applies: "S'applique si", na: "toujours", counts: (d, n) => `${d} domaines · ${n} critères`, profile: "Profil", kv: ["Clé", "Valeur"] }
    : { title: "Motion quality referential", intro: "Criteria audited by `/umd:audit`. Method `auto`: decided in code from measurements; `inspect`: judged by an auditor agent with evidence.", profiles: "Profiles and domain weights", sev: { blocker: "blocker", major: "major", minor: "minor" }, cols: ["ID", "Criterion", "Severity", "Method", "Verification"], th: "Default thresholds", rules: "Build rules", applies: "Applies if", na: "always", counts: (d, n) => `${d} domains · ${n} criteria`, profile: "Profile", kv: ["Key", "Value"] };
  const domains = groups.flatMap((g) => g.domains);
  const n = domains.reduce((s, d) => s + d.criteria.length, 0);
  const L = [GEN, "", `# ${t.title}`, "", `${t.intro}`, "", `**${t.counts(domains.length, n)} · v${VERSION}**`, ""];
  L.push(`## ${t.profiles}`, "", `| ${t.profile} | ${domains.map((d) => d.code).join(" | ")} |`, `| --- | ${domains.map(() => "---").join(" | ")} |`);
  for (const [k, p] of Object.entries(scoring.profiles)) L.push(`| ${p.label[lang]} (\`${k}\`) | ${domains.map((d) => p.weights[d.id]).join(" | ")} |`);
  L.push("", `## ${t.th}`, "", `| ${t.kv[0]} | ${t.kv[1]} |`, "| --- | --- |");
  for (const [k, v] of Object.entries(scoring.thresholds)) if (k !== "_note") L.push(`| \`${k}\` | ${v} |`);
  for (const g of groups) {
    L.push("", `## ${g.label[lang]}`);
    for (const d of g.domains) {
      L.push("", `### ${d.code} — ${d.label[lang]}`, "", d.summary[lang], "", `${t.applies}: ${(d.applies_if || []).join(", ") || t.na}`, "", `**${t.rules}**`, "", ...d.build.map((b) => `- ${b[lang]}`), "");
      L.push(`| ${t.cols.join(" | ")} |`, `| ${t.cols.map(() => "---").join(" | ")} |`);
      for (const c of d.criteria) L.push(`| ${c.id} | ${c.label[lang]}${c.applies_if ? ` _(${c.applies_if.join(", ")})_` : ""} | ${t.sev[c.severity]} | ${c.check.method}${c.check.tool ? ` (${c.check.tool})` : ""} | ${c.verify[lang].replace(/\|/g, "\\|")} |`);
    }
  }
  return L.join("\n") + "\n";
}
write(join(ROOT, "docs", "fr", "REFERENTIEL.md"), doc("fr"));
write(join(ROOT, "docs", "en", "REFERENTIAL.md"), doc("en"));

const pj = join(PLUGIN, ".claude-plugin", "plugin.json");
const plugin = readJson(pj);
plugin.version = VERSION;
write(pj, JSON.stringify(plugin, null, 2) + "\n");
const mj = join(ROOT, ".claude-plugin", "marketplace.json");
const market = readJson(mj);
for (const p of market.plugins) p.version = VERSION;
write(mj, JSON.stringify(market, null, 2) + "\n");

// ---- the motion design skill: one source (tools/skill/SKILL.src.md), two outputs
//   plugins/umd/skills/motion/SKILL.md   the plugin's model-invoked skill (references and CLI through CLAUDE_PLUGIN_ROOT)
//   skills/motion-design/                a standalone skill for any agent (npx skills add), with its own copy of the references
{
  const src = readFileSync(join(ROOT, "tools", "skill", "SKILL.src.md"), "utf8");
  const fill = (vars) => src.replace(/\{\{(\w+)\}\}/g, (_, k) => { if (!(k in vars)) throw new Error("SKILL.src.md: unknown {{" + k + "}}"); return vars[k]; });
  const PR = "${CLAUDE_PLUGIN_ROOT}";
  const pluginChecks = [
    "## Measure, don't guess",
    "",
    "| Question | Command |",
    "| --- | --- |",
    "| What should happen next, and what will it cost? | \`umd next\` |",
    "| Does the look work before animating? | \`umd still <entry> --at 0.5,3,6.5\` |",
    "| Rhythm, stillness, cuts on motion, flashes, black frames, loudness, contact sheet | \`umd analyze <video>\` |",
    "| What happens around each cut? | \`umd frames <video> --cuts\` |",
    "| Does each sound land on its picture? | \`umd sync <video>\` (storyboard \`## Sound cues\`) |",
    "| Are two renders identical? | \`umd render --twice\` or \`umd compare a.mp4 b.mp4\` |",
    "| Hard-coded timings, AI tells, hollow copy, remote assets | \`umd lint\` |",
    "| Licences of dependencies, models and assets | \`umd licenses\` |",
    "| A named technique for the storyboard | \`umd moves <words>\` |",
    "| A free image with its licence recorded | \`umd commons <words>\`, then \`umd commons get \"File:…\"\` |",
    "| Is the animated page smooth and accessible? | \`umd webperf <url>\` |",
  ].join("\n");
  const standaloneChecks = [
    "## Measure, don't guess (plain FFmpeg)",
    "",
    "Without the plugin, these commands give the same evidence. With it, \`umd analyze\`, \`umd sync\` and \`umd audit\` do all of this and score it.",
    "",
    "\`\`\`bash",
    "# contact sheet: 16 frames on one image (look at this before anything else)",
    "ffmpeg -i film.mp4 -vf \"fps=16/DURATION,scale=384:-2,tile=4x4:padding=4\" -frames:v 1 sheet.jpg",
    "# frozen picture (freeze_start / freeze_end over 0.5 s)",
    "ffmpeg -i film.mp4 -vf \"freezedetect=n=0.001:d=0.5\" -an -f null - 2>&1 | grep freeze_",
    "# cuts, with their time",
    "ffmpeg -i film.mp4 -vf \"select='gt(scene,0.3)',metadata=print\" -an -f null - 2>&1 | grep pts_time",
    "# loudness: integrated LUFS and true peak",
    "ffmpeg -i film.mp4 -af ebur128=peak=true -f null - 2>&1 | tail -12",
    "# determinism: identical frame hashes for two renders",
    "ffmpeg -i a.mp4 -f framemd5 - > a.md5; ffmpeg -i b.mp4 -f framemd5 - > b.md5; diff a.md5 b.md5 && echo identical",
    "\`\`\`",
  ].join("\n");
  const plugin = fill({
    NAME: "motion",
    REF: PR + "/references/",
    UMD_LINE: "\`umd\` means \`node \"" + PR + "/scripts/umd.mjs\"\`: it renders HTML to video on a virtual clock, measures, audits 64 checks and guards licences. For a whole piece from brief to delivery, read \`" + PR + "/skills/go/SKILL.md\` and follow it, as if the user had typed \`/umd:go\`: it runs the loop below with its gates and announces each step's token cost.",
    CHECKS_SECTION: pluginChecks,
    STYLES_HINT: ", then \`umd styles <words>\` (784 styles and prompts with previews, no tokens) and \`umd styles get <id>\`",
    PLUGIN_ONLY: "\n## In a umd project\n\n- **Plain-words requests.** When the user asks, without a command, to make, continue, check or deliver a whole piece (\"fais-moi une vidéo de lancement\", \"on continue la vidéo\", \"vérifie la vidéo\"), read \`" + PR + "/skills/go/SKILL.md\` and follow it with their words as arguments.\n- Durations and easings come from \`.motion/motion-tokens.json\`; the style card is in \`BRIEF.md\`; the storyboard is \`.motion/storyboard.md\`; every asset goes in \`.motion/assets.lock.json\`.\n- \`umd rules [domain]\` prints this project's build rules per quality domain, in its language.\n",
  });
  write(join(PLUGIN, "skills", "motion", "SKILL.md"), plugin);
  const standalone = fill({
    NAME: "motion-design",
    REF: "references/",
    UMD_LINE: "This skill works on its own in any coding agent. For deterministic HTML-to-video rendering, the 64-check audit scored out of 10, the 784-style library and the licence guard, add the Ultimate Motion Design plugin (Claude Code: \`/plugin marketplace add 1AngelMicka/ultimate-motion-design\`, then \`/plugin install umd@ultimate-motion-design\`; docs: https://1angelmicka.github.io/ultimate-motion-design/). The references below mention its \`umd\` commands; the plain-FFmpeg section gives the same checks without it.",
    CHECKS_SECTION: standaloneChecks,
    STYLES_HINT: " (the plugin searches 784 styles with previews: \`umd styles <words>\`)",
    PLUGIN_ONLY: "",
  });
  const SK = join(ROOT, "skills", "motion-design");
  write(join(SK, "SKILL.md"), standalone);
  const refRoot = join(PLUGIN, "references");
  const copyDir = (rel) => {
    for (const e of readdirSync(join(refRoot, rel), { withFileTypes: true })) {
      const r = rel ? rel + "/" + e.name : e.name;
      if (e.isDirectory()) { if (!["styles", "moves"].includes(e.name)) copyDir(r); continue; }
      if (!e.name.endsWith(".md") || e.name === "companions.md") continue;
      write(join(SK, "references", r), readFileSync(join(refRoot, r), "utf8"));
    }
  };
  copyDir("");
  write(join(SK, "LICENSE"), readFileSync(join(ROOT, "LICENSE"), "utf8"));
}

// Numbers stated in the docs must match the data: a forgotten "58 checks" fails the check
{
  const all = groups.flatMap((g) => g.domains).flatMap((d) => d.criteria);
  const total = all.length, auto = all.filter((c) => c.check.method === "auto").length, lic = licenses.entries.length;
  const files = ["README.md", "README.en.md", "AGENTS.md", "llms.txt", ...["fr", "en"].flatMap((l) => readdirSync(join(ROOT, "site", "content", l)).map((f) => `site/content/${l}/${f}`))];
  const bad = [];
  for (const f of files) {
    const text = readFileSync(join(ROOT, f), "utf8");
    const lines = text.split(/\r?\n/);
    lines.forEach((line, i) => {
      for (const m of line.matchAll(/(\d+) (?:quality )?(?:checks|vérifications|critères|criteria)\b(?! ou moins| or fewer| or less)/g)) {
        const n = Number(m[1]); const before = line.slice(0, m.index);
        if (/(des|of the|sur)\s*$/.test(before)) continue; // "28 des 60" handled below
        if (n !== total && n !== auto && !/\b(\d+) (?:des|of the)\s*$/.test(before)) bad.push(`${f}:${i + 1} says ${n} checks (data: ${total}, ${auto} automatic)`);
      }
      for (const m of line.matchAll(/(\d+) (?:des|of the|vérifications sur|checks out of) (\d+)/g)) {
        if (Number(m[2]) !== total || Number(m[1]) !== auto) bad.push(`${f}:${i + 1} says ${m[1]} of ${m[2]} (data: ${auto} of ${total})`);
      }
      for (const m of line.matchAll(/(?:registre compte|registry has) (\d+) entr/g)) if (Number(m[1]) !== lic) bad.push(`${f}:${i + 1} says ${m[1]} licence entries (data: ${lic})`);
    });
  }
  if (bad.length) { console.error(`Docs disagree with the data:\n- ${bad.join("\n- ")}`); process.exit(1); }
}

if (stale.length) { console.error(`Out of date (run node tools/build.mjs):\n- ${stale.join("\n- ")}`); process.exit(1); }
console.log(`OK: ${groups.flatMap((g) => g.domains).length} domains, ${ids.size} criteria, ${Object.keys(scoring.profiles).length} profiles, ${licenses.entries.length} licence entries, v${VERSION}${check ? " (check)" : ""}`);
